/* CyberChef v11.5.0 中文本地化 - 运行时显示层
 * 逻辑键（操作名 / 分类名 / 选项 value）一律保持英文，
 * 仅在 DOM 显示层替换，保证 recipe URL、双击添加、收藏与搜索不受影响。
 */
(function () {
    "use strict";
    var D = window.__CCZH__;
    if (!D) return;

    var UI = D.ui, ARGS = D.args, OPTS = D.opts,
        VOPTS = D.valueOpts, OPS = D.ops, CATS = D.cats;
    var has = function (o, k) { return Object.prototype.hasOwnProperty.call(o, k); };
    var RE_BILING = /^(.*)（([^（）]+)）$/;

    /* 把「中文（English）」还原成英文，供 addOperation(t.textContent) 使用 */
    window.__CCZH_UNTRANSLATE__ = function (s) {
        if (!s) return s;
        var t = String(s).trim(), m = RE_BILING.exec(t);
        if (m && (has(OPS, m[2]) || has(CATS, m[2]))) return m[2];
        return s;
    };

    function lookup(t) {
        if (has(UI, t)) return UI[t];
        if (has(ARGS, t)) return ARGS[t];
        if (has(OPTS, t)) return OPTS[t];
        if (has(VOPTS, t)) return VOPTS[t];
        return null;
    }

    /* data-help-title 是 CyberChef 悬浮帮助面板的标题（Last build / Input status bar 等） */
    var ATTRS = ["title", "data-original-title", "data-content", "placeholder",
                 "aria-label", "alt", "data-title", "data-help", "data-help-title"];
    /* Only skip real editable/verbatim content.  CodeMirror status bars and
       gutter panels live inside .cm-editor but must still be translatable. */
    var SKIP_SEL = ".cm-content,.cm-line,.CodeMirror-code,script,style,pre,code,textarea";

    function skipped(node) {
        var e = node.nodeType === 1 ? node : node.parentElement;
        if (!e || !e.closest) return false;
        try { return !!e.closest(SKIP_SEL); } catch (x) { return false; }
    }

    function handleText(node) {
        if (node.nodeType !== 3 || skipped(node)) return;
        var raw = node.nodeValue, t = raw.trim();
        if (!t || /[\u4e00-\u9fff]/.test(t)) return;
        if (RE_BILING.test(t)) return;

        /* 分类 / 操作名：中英对照 */
        if (has(CATS, t)) {
            node.nodeValue = raw.replace(t, CATS[t] + "（" + t + "）");
            return;
        }
        if (has(OPS, t)) {
            node.nodeValue = raw.replace(t, OPS[t] === t ? t : OPS[t] + "（" + t + "）");
            return;
        }
        var v = lookup(t);
        if (v) node.nodeValue = raw.replace(t, v);
    }

    /* 动态拼接的状态栏/帮助正文里仍夹杂固定英文短语 */
    var PHRASES = [
        ["Input encoding:", "输入编码："],
        ["Recipe duration:", "配方耗时："],
        ["Output decoding:", "输出解码："],
        ["Threading overhead:", "线程开销："],
        ["on Wikipedia", "在维基百科上"],
        ["More Information", "更多信息"],
        ["End of line sequence:", "行尾序列："],
        ["Input character encoding:", "输入字符编码："],
        ["Output character encoding:", "输出字符编码："],
        ["Raw Bytes", "原始字节"],
        ["Line Feed", "换行符"],
        ["Operation error timeout", "操作错误超时"],
        ["Baking time", "执行耗时"]
    ];

    function applyPhrases(seg) {
        for (var i = 0; i < PHRASES.length; i++) {
            if (seg.indexOf(PHRASES[i][0]) >= 0) {
                seg = seg.split(PHRASES[i][0]).join(PHRASES[i][1]);
            }
        }
        return seg;
    }

    /* 属性（tooltip / popover / placeholder）：整串查表 + 分段查表 + 短语替换 */
    function translateAttr(v) {
        var t = v.trim();
        if (!t || !/[A-Za-z]/.test(t)) return v;
        if (!/[\u4e00-\u9fff]/.test(t)) {
            var direct = lookup(t);
            if (direct) return v.replace(t, direct);
        }
        return v.replace(/[^<>]+/g, function (seg) {
            var st = seg.trim();
            var out = seg;
            if (st && !/[\u4e00-\u9fff]/.test(st)) {
                var r = lookup(st);
                if (r) out = seg.replace(st, r);
            }
            return applyPhrases(out);
        });
    }

    function handleAttrs(el) {
        if (el.nodeType !== 1 || !el.getAttribute) return;
        for (var i = 0; i < ATTRS.length; i++) {
            var a = ATTRS[i], v = el.getAttribute(a);
            if (!v || !/[A-Za-z]/.test(v)) continue;
            var nv = translateAttr(v);
            if (nv !== v) el.setAttribute(a, nv);
        }
    }

    /* 下拉选项：只改显示文本，强制把英文原文保留为 value */
    function handleOption(el) {
        if (el.nodeType !== 1 || el.tagName !== "OPTION") return;
        var t = (el.textContent || "").trim();
        if (!t || /[\u4e00-\u9fff]/.test(t)) return;
        var v = (has(VOPTS, t) && VOPTS[t]) || (has(ARGS, t) && ARGS[t]) ||
                (has(OPTS, t) && OPTS[t]) || (has(UI, t) && UI[t]);
        if (v && v !== t) {
            if (!el.hasAttribute("value")) el.setAttribute("value", t);
            el.textContent = v;
        }
    }

    /* 搜索结果下拉（#search-results li）：命中的字符被 <b> 高亮标记拆进不同文本节点，
       整词查表失效，因此一直显示英文。这里按 li 整体重建为「中文（English）」，
       保留 <b> 高亮；重建后的 textContent 是双语，回车 / 双击 / 拖拽添加时
       仍由 __CCZH_UNTRANSLATE__ 还原为英文内部键，不受影响。 */
    function handleSearchResults(root) {
        if (root.nodeType !== 1) return;
        var lis;
        try {
            if (root.tagName === "LI" && root.parentElement &&
                root.parentElement.id === "search-results") {
                lis = [root];
            } else {
                lis = root.querySelectorAll("#search-results > li");
            }
        } catch (e) { return; }
        for (var i = 0; i < lis.length; i++) {
            var li = lis[i];
            if (li.getAttribute("data-cczh-bil") === "1") continue;
            var plain = (li.textContent || "").trim();
            if (!plain || /[\u4e00-\u9fff]/.test(plain)) continue;
            if (!has(OPS, plain)) continue;
            var zh = OPS[plain];
            if (!zh || zh === plain) continue;
            li.setAttribute("data-cczh-bil", "1");
            li.innerHTML = zh + "（" + li.innerHTML + "）";
        }
    }

    function scan(root) {
        if (!root) return;
        try {
            if (root.nodeType === 1) {
                handleSearchResults(root);
                handleAttrs(root);
                handleOption(root);
                var els = root.querySelectorAll("*");
                for (var i = 0; i < els.length; i++) {
                    handleAttrs(els[i]);
                    if (els[i].tagName === "OPTION") handleOption(els[i]);
                }
            }
            var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
            var n, list = [];
            while ((n = walker.nextNode())) list.push(n);
            for (var j = 0; j < list.length; j++) handleText(list[j]);
        } catch (e) { /* never break the host app */ }
    }

    var pending = [], scheduled = false;
    function flush() {
        scheduled = false;
        var roots = pending.splice(0);
        for (var i = 0; i < roots.length; i++) scan(roots[i]);
    }
    function schedule(nodes) {
        for (var i = 0; i < nodes.length; i++) pending.push(nodes[i]);
        if (!scheduled) { scheduled = true; (window.requestAnimationFrame || setTimeout)(flush, 16); }
    }

    function boot() {
        scan(document.body);
        var mo = new MutationObserver(function (muts) {
            var added = [];
            for (var i = 0; i < muts.length; i++) {
                var m = muts[i];
                if (m.type === "childList") {
                    for (var j = 0; j < m.addedNodes.length; j++) {
                        var n = m.addedNodes[j];
                        if (n.nodeType === 1 || n.nodeType === 3) added.push(n);
                    }
                } else if (m.type === "attributes" && m.target.nodeType === 1) {
                    handleAttrs(m.target);
                }
            }
            if (added.length) schedule(added);
        });
        mo.observe(document.documentElement, {
            childList: true, subtree: true, attributes: true, attributeFilter: ATTRS
        });
        /* 初始化阶段面板分批生成，做有限次兜底全量扫描 */
        var ticks = 0;
        var timer = setInterval(function () {
            scan(document.body);
            if (++ticks >= 12) clearInterval(timer);
        }, 700);
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", boot);
    } else {
        boot();
    }
})();
